// FUNCTION: BFME2 0x00712A30 size=211 name=?Get_Orthogonal_Inverse@Matrix3D@@QBEXAAV1@@Z evidence=N:ledger tier=A
void Matrix3D::Get_Orthogonal_Inverse(Matrix3D &inv) const
{
	// The rotation part is transposed; the translation is minus that rotation applied to ours.
	inv.Row[0].X = Row[0].X;
	inv.Row[0].Y = Row[1].X;
	inv.Row[0].Z = Row[2].X;
	inv.Row[1].X = Row[0].Y;
	inv.Row[1].Y = Row[1].Y;
	inv.Row[1].Z = Row[2].Y;
	inv.Row[2].X = Row[0].Z;
	inv.Row[2].Y = Row[1].Z;
	inv.Row[2][2] = Row[2][2];

	Vector3 trans(Row[0][3], Row[1][3], Row[2][3]);
	Vector3 rotated = inv.Rotate_Vector(trans);
	inv.Row[0][3] = -rotated[0];
	inv.Row[1][3] = -rotated[1];
	inv.Row[2][3] = -rotated[2];
}

