// FUNCTION: BFME2 0x00712B60 size=319 name=?Transform_Min_Max_AABox@Matrix3D@@QBEXABVVector3@@0PAV2@1@Z evidence=N:ledger tier=A
void Matrix3D::Transform_Min_Max_AABox(const Vector3 &min, const Vector3 &max, Vector3 *set_min, Vector3 *set_max) const
{
	// Start from the translation, then add each axis's smaller and larger contribution.
	set_min->X = set_max->X = Row[0][3];
	set_min->Y = set_max->Y = Row[1][3];
	set_min->Z = set_max->Z = Row[2][3];

	for (int i = 0; i < 3; i++) {
		for (int j = 0; j < 3; j++) {
			float lo = min[j] * Row[i][j];
			float hi = max[j] * Row[i][j];
			if (lo < hi) {
				(*set_min)[i] += lo;
				(*set_max)[i] += hi;
			} else {
				(*set_min)[i] += hi;
				(*set_max)[i] += lo;
			}
		}
	}
}

// FUNCTION: BFME2 0x00712CA0 size=236 name=?Transform_Center_Extent_AABox@Matrix3D@@QBEXABVVector3@@0PAV2@1@Z evidence=N:ledger tier=A
void Matrix3D::Transform_Center_Extent_AABox(const Vector3 &center, const Vector3 &extent, Vector3 *set_center, Vector3 *set_extent) const
{
	for (int i = 0; i < 3; i++) {
		(*set_center)[i] = Row[i][3];
		(*set_extent)[i] = 0.0f;
		for (int j = 0; j < 3; j++) {
			(*set_center)[i] += center[j] * Row[i][j];
			(*set_extent)[i] += WWMath::Fabs(Row[i][j] * extent[j]);
		}
	}
}

// FUNCTION: BFME2 0x00712D90 size=416 name=?Is_Orthogonal@Matrix3D@@QBEHXZ evidence=N:ledger tier=A
int Matrix3D::Is_Orthogonal(void) const
{
	const float tolerance = 0.0001f;
	Vector3 x(Row[0][0], Row[0][1], Row[0][2]);
	Vector3 y(Row[1][0], Row[1][1], Row[1][2]);
	Vector3 z(Row[2][0], Row[2][1], Row[2][2]);

	// The three axes must be mutually perpendicular and of unit length.
	if (x.X * y.X + x.Y * y.Y + x.Z * y.Z > tolerance) return 0;
	if (y.X * z.X + y.Y * z.Y + y.Z * z.Z > tolerance) return 0;
	if (z.X * x.X + z.Y * x.Y + z.Z * x.Z > tolerance) return 0;

	if (WWMath::Fabs(x.X * x.X + x.Y * x.Y + x.Z * x.Z - 1.0f) > tolerance) return 0;
	if (WWMath::Fabs(y.X * y.X + y.Y * y.Y + y.Z * y.Z - 1.0f) > tolerance) return 0;
	if (WWMath::Fabs(z.X * z.X + z.Y * z.Y + z.Z * z.Z - 1.0f) > tolerance) return 0;
	return 1;
}

// FUNCTION: BFME2 0x00712F30 size=809 name=?Solve_Linear_System@Matrix3D@@SA_NAAV1@@Z evidence=N:ledger tier=A
bool Matrix3D::Solve_Linear_System(Matrix3D &system)
{
	/*
	** Gauss-Jordan Elimination
	** We repeatedly replace rows in the matrix with a linear combination of itself and
	** another row in the system in order to reduce the matrix to the identity matrix.
	*/

	if (system[0][0] == 0.0f) return false;
	system[0] *= 1.0f / system[0][0];				// (0,0) now equals 1.0  (row,col)
	system[1] -= system[1][0] * system[0];			// (1,0) now equals 0.0
	system[2] -= system[2][0] * system[0];			// (2,0) now equals 0.0

	if (system[1][1] == 0.0f) return false;
	system[1] *= 1.0f / system[1][1];				// (1,1) now equals 1.0
	system[2] -= system[2][1] * system[1];			// (2,1) now equals 0.0

	if (system[2][2] == 0.0f) return false;
	system[2] *= 1.0f / system[2][2];				// (2,2) now equals 1.0, and we already have one answer
	system[1] -= system[1][2] * system[2];			// (1,2) now equals 0.0, and we have another answer
	system[0] -= system[0][2] * system[2];			// (0,2) now equals 0.0
	system[0] -= system[0][1] * system[1];			// (0,1) now equals 0.0, and we are done!

	return true;
}

